import sys, re

TOKEN = re.compile(r'-?[0-9]+|"[a-z0-9]+"|true|false|null|\{\}')

def main():
    text = sys.stdin.read().strip()
    groups = {'number': {}, 'string': {}, 'boolean': {}, 'null': {}, 'object': {}}
    for t in TOKEN.findall(text):
        if t[0] == '"':
            g, k = 'string', t[1:-1]
        elif t == 'true' or t == 'false':
            g, k = 'boolean', t
        elif t == 'null':
            g, k = 'null', t
        elif t == '{}':
            g, k = 'object', t
        else:
            g, k = 'number', int(t)
        groups[g][k] = groups[g].get(k, 0) + 1
    lines = []
    for g in ('number', 'string', 'boolean', 'null', 'object'):
        d = groups[g]
        if d:
            lines.append(g + ''.join(' %s:%d' % (k, d[k]) for k in sorted(d)))
    print('\n'.join(lines) if lines else 'EMPTY')

main()

