def parse_array():
    global pos
    assert s[pos] == '['
    pos += 1
    items = []
    while s[pos] != ']':
        if s[pos] == ',':
            pos += 1
            continue
        items.append(parse_value())
    pos += 1
    return items

def parse_value():
    global pos
    c = s[pos]
    if c == '[':
        return parse_array()
    if c == '"':
        e = s.index('"', pos + 1)
        v = ('string', s[pos + 1:e])
        pos = e + 1
        return v
    if c == '{':
        pos += 2
        return ('object', '{}')
    for w in ('true', 'false', 'null'):
        if s.startswith(w, pos):
            pos += len(w)
            return ('boolean' if w != 'null' else 'null', w)
    e = pos + 1
    while s[e] not in ',]':
        e += 1
    v = ('number', int(s[pos:e]))
    pos = e
    return v

def flatten(x, out):
    if isinstance(x, list):
        for y in x:
            flatten(y, out)
    else:
        out.append(x)

