def gen(rng):
    def make_val(pool):
        r = rng.random()
        if r < 0.35:
            return str(rng.choice(pool['nums']))
        if r < 0.65:
            return '"%s"' % rng.choice(pool['strs'])
        if r < 0.75:
            return rng.choice(['true', 'false'])
        if r < 0.85:
            return 'null'
        return '{}'
    def make(nvals, maxdepth, popen, pclose, pool):
        out = ['[']
        need = [False]
        depth = 1
        for _ in range(nvals):
            while rng.random() < popen and depth < maxdepth:
                if need[-1]:
                    out.append(',')
                out.append('[')
                need[-1] = True
                need.append(False)
                depth += 1
            while depth > 1 and rng.random() < pclose:
                out.append(']')
                need.pop()
                depth -= 1
            if need[-1]:
                out.append(',')
            out.append(make_val(pool))
            need[-1] = True
        while depth > 0:
            out.append(']')
            depth -= 1
        return ''.join(out)
    small = {'nums': list(range(-3, 6)), 'strs': ['a', 'b', 'ab', '1', '3', 'x9', 'true', 'null']}
    tests = [
        '[]',
        '[[],[[]]]',
        '[[[[]]]]',
        '[1]',
        '[{}]',
        '[null,null,[null]]',
        '[1,"a",[true,["b",null],[{},null]],1]',
        '[3,"3",-1,[3,[3,"3"]],false,true,false]',
        '["true","null","false",true,null,false]',
        '[0,1000000000,-1000000000,[10,2,1,-10,-2]]',
    ]
