        for _ in range(4):
            tests.append(make(nv, 6, 0.4, 0.4, small))
    # large: many distinct numbers and strings
    def big_pool(nnums, nstrs):
        al = 'abcdefghijklmnopqrstuvwxyz0123456789'
        strs = set()
        while len(strs) < nstrs:
            strs.add(''.join(rng.choice(al) for _ in range(rng.randint(1, 8))))
        return {'nums': [rng.randint(-10**9, 10**9) for _ in range(nnums)], 'strs': sorted(strs)}
    tests.append(make(200000, 50, 0.5, 0.5, big_pool(30000, 30000)))
    tests.append(make(200000, 8, 0.3, 0.6, small))
    tests.append(make(200000, 3000, 0.9, 0.1, big_pool(100, 100)))
    # exactly depth 5000
    tests.append('[' * 4999 + '[1,"a",null,{},true,1]' + ']' * 4999)
    tests.append('[' * 5000 + ']' * 5000)
